// Place in Zabbix frontend under Configuration → Actions → Event correlation
{
  "name": "Silence agent not available alerts on test VMs",
  "eventsource": 0, // Triggers
  "status": 0, // Enabled
  "filter": {
    "evaltype": 0,
    "conditions": [
      {"conditiontype": 16, "operator": 8, "value": "*-test-vm-*"}, // Host name pattern
      {"conditiontype": 12, "operator": 8, "value": "agent is not available"}, // Problem name contains
      {"conditiontype": 15, "operator": 8, "value": "Average"} // Severity in minor/warning/info mapped to Average
    ]
  },
  "operations": [
    {
      "operationtype": 7, // Event suppression
      "esc_period": 1440,
      "esc_step_from": 1,
      "esc_step_to": 1,
      "evaltype": 0,
      "opconditions": [],
      "opcommand_hst": [],
      "opmessage_grp": [],
      "opmessage_usr": []
    }
  ]
}

